428	 snip:`<span class="cm"># custom_block.py:114</span>
429	<span class="kw">def</span> <span class="fn">_make_handler</span>(template):
430	    <span class="kw">def</span> <span class="fn">handler</span>(cmd):
431	        <span class="kw">if not</span> template: <span class="kw">return</span> <span class="str">""</span>
432	        <span class="kw">if</span> <span class="str">"{"</span> <span class="kw">not in</span> template: <span class="kw">return</span> template
433	        <span class="kw">try</span>: <span class="kw">return</span> template.<span class="fn">format</span>(*cmd.params)
