436	 c:[{l:'template.format(*cmd.params) substitutes SCPI params',t:['format','cmd.params','params','substitute','{0}']},
437	    {l:'"ECHO 42" → cmd.params = ["42"] → echo:42',t:['echo:42','42','echo:']},
438	    {l:'empty template → write-only (returns "")',t:['empty','write-only','""','no response']},
439	    {l:'no { in template → return verbatim',t:['no {','verbatim','literal','no brace']}],
440	 m:`_make_handler(template) is a closure factory. For "echo:{0}":
441	- "{" is in the template, so the format path runs.
